import { createHash } from 'node:crypto';
import { roles, teams } from './team-routing-contract-audit.mjs';

// A deterministic foreground workflow reducer, not a transport or approval engine.
// The adapter must validate the sealed router contract and real receipts. No IDs
// for provider threads, raw conversations, or credentials belong in this state.
const hash = (value) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const idPattern = /^[A-Z][A-Z0-9_-]{0,100}$/;
const evidencePattern = /^(TASK|ARTIFACT|RECEIPT):[A-Za-z0-9_.:/#-]{1,240}$/;
function requireValue(condition, code) {
  if (!condition) throw new Error(code);
}

export function createServiceWorkflow({ taskId, correlationId, team, taskPointer }) {
  requireValue(idPattern.test(taskId ?? '') && idPattern.test(correlationId ?? ''), 'INVALID_TASK_ID');
  requireValue(teams.includes(team), 'INVALID_TEAM');
  requireValue(typeof taskPointer === 'string' && evidencePattern.test(taskPointer), 'INVALID_TASK_POINTER');
  // The situation room is a status consumer, not a mandatory dispatch hop.
  const path = [roles.human, roles.master, roles.deputy, team, roles.deputy, roles.master, roles.human];
  const kinds = ['REQUEST', 'TASK_DISPATCH', 'TASK_DISPATCH', 'TASK_RESULT', 'AGGREGATE_RESULT', 'AGGREGATE_RESULT'];
  return {
    schemaVersion: 1, taskId, correlationId, taskPointer, team,
    revision: 0, status: 'READY', leg: 0, activeDeliveryToken: null,
    legs: kinds.map((kind, index) => ({ source: path[index], target: path[index + 1], kind })),
    seen: {}, receipts: [], resultPointer: null, blocker: null,
  };
}

export function nextServiceAction(state, actor) {
  if (['COMPLETED', 'STOPPED', 'REJECTED'].includes(state.status)) return { type: 'TERMINAL', status: state.status };
  if (state.status === 'BLOCKED') {
    if (actor !== state.blocker.source) return { type: 'WAIT_FOR_ACTOR', logicalActor: state.blocker.source };
    return { type: 'REPORT_BLOCKER', ...state.blocker, requiresRouterValidation: true };
  }
  const leg = state.legs[state.leg];
  if (state.status !== 'READY') return { type: 'WAIT_FOR_RECEIPT', deliveryToken: state.activeDeliveryToken };
  if (actor !== leg.source) return { type: 'WAIT_FOR_ACTOR', logicalActor: leg.source };
  return {
    type: 'PREPARE_ROUTE', ...leg, taskId: state.taskId, correlationId: state.correlationId,
    payload: { task_pointer: state.taskPointer, result_pointer: state.resultPointer, workflow_leg: state.leg },
    // Only direction, never execution permission. prepare-dispatch still enforces
    // caller endpoint, mission, activation, kind, scope, lock and dedupe.
    childRoutesNeeded: state.leg < state.legs.length - 1,
    requiresRouterValidation: true,
  };
}

export function applyServiceEvent(state, event, { verifyReceipt } = {}) {
  requireValue(event && idPattern.test(event.eventId ?? ''), 'INVALID_EVENT_ID');
  const fingerprint = hash(event);
  if (Object.hasOwn(state.seen, event.eventId)) {
    requireValue(state.seen[event.eventId] === fingerprint, 'EVENT_ID_CONFLICT');
    return state;
  }
  requireValue(event.expectedRevision === state.revision, 'REVISION_CONFLICT');
  requireValue(event.taskId === state.taskId && event.correlationId === state.correlationId, 'TASK_SCOPE_MISMATCH');
  requireValue(!['COMPLETED', 'STOPPED', 'REJECTED'].includes(state.status), 'TERMINAL_WORKFLOW');
  requireValue(state.receipts.length < 100, 'EVENT_LIMIT_REQUIRES_CHECKPOINT');
  requireValue(typeof event.evidencePointer === 'string' && evidencePattern.test(event.evidencePointer), 'EVIDENCE_REQUIRED');
  const leg = state.legs[state.leg];
  requireValue(typeof verifyReceipt === 'function'
    && verifyReceipt({ state, event, leg }) === true, 'RECEIPT_NOT_VERIFIED');
  const next = structuredClone(state);
  switch (event.type) {
    case 'TOOL_ACCEPTED':
      requireValue(state.status === 'READY' && event.actor === leg.source, 'INVALID_SEND_STATE');
      requireValue(typeof event.deliveryToken === 'string' && /^DELIVERY-[A-Za-z0-9-]{1,100}$/.test(event.deliveryToken), 'DELIVERY_TOKEN_REQUIRED');
      requireValue(!state.receipts.some((receipt) => receipt.type === 'TOOL_ACCEPTED'
        && receipt.deliveryToken === event.deliveryToken), 'DELIVERY_TOKEN_REUSED');
      next.activeDeliveryToken = event.deliveryToken;
      next.status = 'SENT_UNCONFIRMED';
      break;
    case 'ACK':
      requireValue(state.status === 'SENT_UNCONFIRMED' && event.actor === leg.target, 'INVALID_ACK_STATE');
      requireValue(event.deliveryToken === state.activeDeliveryToken, 'DELIVERY_TOKEN_MISMATCH');
      next.status = 'ACKNOWLEDGED';
      break;
    case 'LEG_COMPLETED':
      requireValue(state.status === 'ACKNOWLEDGED' && event.actor === leg.target, 'INVALID_RESULT_STATE');
      requireValue(event.deliveryToken === state.activeDeliveryToken, 'DELIVERY_TOKEN_MISMATCH');
      requireValue(typeof event.resultPointer === 'string' && evidencePattern.test(event.resultPointer), 'RESULT_POINTER_REQUIRED');
      next.resultPointer = event.resultPointer;
      next.leg += 1;
      next.activeDeliveryToken = null;
      next.status = next.leg === next.legs.length ? 'COMPLETED' : 'READY';
      break;
    case 'REJECTED':
      requireValue(['SENT_UNCONFIRMED', 'ACKNOWLEDGED'].includes(state.status)
        && event.actor === leg.target && event.deliveryToken === state.activeDeliveryToken, 'INVALID_REJECTION');
      next.status = 'REJECTED';
      break;
    case 'BLOCKED':
      requireValue(state.status !== 'BLOCKED' && [leg.source, leg.target].includes(event.actor), 'INVALID_BLOCKER');
      next.status = 'BLOCKED';
      next.blocker = { source: event.actor, target: roles.human, kind: 'DECISION_POINTER', evidencePointer: event.evidencePointer };
      break;
    case 'HUMAN_STOP':
      // The adapter must verify an actual human decision; a role name is not proof.
      requireValue(event.actor === roles.human, 'HUMAN_DECISION_REQUIRED');
      next.status = 'STOPPED';
      break;
    default:
      throw new Error('UNSUPPORTED_EVENT');
  }
  next.revision += 1;
  next.seen[event.eventId] = fingerprint;
  next.receipts.push({ type: event.type, leg: state.leg, evidencePointer: event.evidencePointer,
    deliveryToken: event.deliveryToken ?? null });
  return next;
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { createServiceWorkflow, nextServiceAction, applyServiceEvent } from './team-service-workflow.mjs';
import { roles, teams } from './team-routing-contract-audit.mjs';

const initial = () => createServiceWorkflow({ taskId: 'TASK-PILOT', correlationId: 'CORR-PILOT', team: teams[1], taskPointer: 'TASK:TASK-PILOT' });
// Synthetic receipts are test-only. Production MUST supply its real verifier.
const fixtureVerifier = { verifyReceipt: () => true };
const eventFor = (s, type, extra = {}) => ({ eventId: `EVENT-${s.revision}`, expectedRevision: s.revision,
  taskId: s.taskId, correlationId: s.correlationId, type, actor: s.legs[s.leg].target,
  evidencePointer: `RECEIPT:TEST-${s.revision}`, deliveryToken: s.activeDeliveryToken, ...extra });
const send = (s) => applyServiceEvent(s, eventFor(s, 'TOOL_ACCEPTED', { actor: s.legs[s.leg].source, deliveryToken: `DELIVERY-${s.leg}` }), fixtureVerifier);
const ack = (s) => applyServiceEvent(s, eventFor(s, 'ACK'), fixtureVerifier);

test('ordinary assignment goes 01 to CEO to service chief to team, never via room', () => {
  const state = initial();
  assert.deepEqual(state.legs.slice(0, 3).map(({ source, target }) => [source, target]),
    [[roles.human, roles.master], [roles.master, roles.deputy], [roles.deputy, teams[1]]]);
  assert.equal(nextServiceAction(state, roles.human).requiresRouterValidation, true);
  assert.equal(nextServiceAction(state, roles.master).type, 'WAIT_FOR_ACTOR');
});

test('tool acceptance is not ACK, and ACK is not task completion', () => {
  const sent = send(initial());
  assert.equal(sent.status, 'SENT_UNCONFIRMED');
  assert.equal(sent.leg, 0);
  assert.throws(() => applyServiceEvent(sent, eventFor(sent, 'LEG_COMPLETED', { resultPointer: 'ARTIFACT:RESULT' }), fixtureVerifier), /INVALID_RESULT_STATE/);
  assert.equal(ack(sent).status, 'ACKNOWLEDGED');
  assert.equal(ack(sent).leg, 0);
});

test('six-leg synthetic roundtrip advances only on verified result at each hop', () => {
  let state = initial();
  for (let i = 0; i < 6; i++) {
    state = ack(send(state));
    state = applyServiceEvent(state, eventFor(state, 'LEG_COMPLETED', { resultPointer: `ARTIFACT:RESULT-${i}` }), fixtureVerifier);
    state = JSON.parse(JSON.stringify(state));
  }
  assert.equal(state.status, 'COMPLETED');
  assert.equal(state.revision, 18);
  assert.equal(nextServiceAction(state, roles.human).type, 'TERMINAL');
});

test('missing or negative receipt verification fails closed', () => {
  const s = initial();
  const e = eventFor(s, 'TOOL_ACCEPTED', { actor: roles.human, deliveryToken: 'DELIVERY-0' });
  assert.throws(() => applyServiceEvent(s, e), /RECEIPT_NOT_VERIFIED/);
  assert.throws(() => applyServiceEvent(s, e, { verifyReceipt: () => false }), /RECEIPT_NOT_VERIFIED/);
});

test('same event is idempotent; changed event, wrong scope and stale revision fail', () => {
  const s = send(initial());
  const e = eventFor(s, 'ACK');
  const result = applyServiceEvent(s, e, fixtureVerifier);
  assert.equal(applyServiceEvent(result, e, fixtureVerifier), result);
  assert.throws(() => applyServiceEvent(result, { ...e, evidencePointer: 'RECEIPT:OTHER' }, fixtureVerifier), /EVENT_ID_CONFLICT/);
  assert.throws(() => applyServiceEvent(s, { ...e, taskId: 'OTHER' }, fixtureVerifier), /TASK_SCOPE_MISMATCH/);
  assert.throws(() => applyServiceEvent(s, { ...e, expectedRevision: 0 }, fixtureVerifier), /REVISION_CONFLICT/);
});

test('wrong actor or delivery token cannot acknowledge', () => {
  const s = send(initial());
  assert.throws(() => applyServiceEvent(s, eventFor(s, 'ACK', { actor: roles.deputy }), fixtureVerifier), /INVALID_ACK_STATE/);
  assert.throws(() => applyServiceEvent(s, eventFor(s, 'ACK', { deliveryToken: 'DELIVERY-WRONG' }), fixtureVerifier), /DELIVERY_TOKEN_MISMATCH/);
});

test('rejection is terminal and not retried as an ACK', () => {
  const s = send(initial());
  const rejected = applyServiceEvent(s, eventFor(s, 'REJECTED'), fixtureVerifier);
  assert.equal(nextServiceAction(rejected, roles.human).type, 'TERMINAL');
  assert.throws(() => applyServiceEvent(rejected, eventFor(rejected, 'ACK'), fixtureVerifier), /TERMINAL_WORKFLOW/);
});

test('blocker goes directly to human intake; human stop prevents new work', () => {
  const s = initial();
  const blocked = applyServiceEvent(s, eventFor(s, 'BLOCKED'), fixtureVerifier);
  assert.equal(nextServiceAction(blocked, roles.master).target, roles.human);
  assert.equal(nextServiceAction(blocked, roles.deputy).type, 'WAIT_FOR_ACTOR');
  const stopped = applyServiceEvent(blocked, eventFor(blocked, 'HUMAN_STOP', { actor: roles.human }), fixtureVerifier);
  assert.equal(nextServiceAction(stopped, roles.master).status, 'STOPPED');
});

test('transition does not mutate the prior checkpoint', () => {
  const s = initial();
  const before = JSON.stringify(s);
  send(s);
  assert.equal(JSON.stringify(s), before);
});

test('invalid team and empty or raw task payload are refused', () => {
  assert.throws(() => createServiceWorkflow({ taskId: 'TASK-A', correlationId: 'CORR-A', team: roles.room, taskPointer: 'TASK:A' }), /INVALID_TEAM/);
  assert.throws(() => createServiceWorkflow({ taskId: 'TASK-A', correlationId: 'CORR-A', team: teams[0], taskPointer: 'raw conversation' }), /INVALID_TASK_POINTER/);
});

import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseFrontMatter } from './docs-graph-check.mjs';

// Read-only requirement coverage, NOT routing permission or a delivery verifier.
// Keep separate from the currently sealed v2 graph until a reviewed migration.
export const roles = Object.freeze({
  human: 'MASTER-01-HUMAN-DECISIONS',
  master: 'MASTER-02-ORCHESTRATION',
  deputy: 'MASTER-03-DEPUTY-CONTEXT',
  room: 'DEPARTMENT-00-ALL-TEAMS-ROOM',
  staging: 'MASTER-04-DEVELOPMENT-STAGING',
  production: 'MASTER-05-PRODUCTION-RECOVERY',
});
export const teams = Object.freeze([
  'DEPARTMENT-01-PRODUCT-MOBILE', 'DEPARTMENT-02-DATA-BACKEND',
  'DEPARTMENT-03-SERVER-OPERATIONS', 'DEPARTMENT-04-QUALITY-REVIEW',
  'DEPARTMENT-05-KNOWLEDGE-ORCHESTRATION',
]);
const expectedIds = [...Object.values(roles), ...teams];

export function auditRoutingCoverage(manifests) {
  const byId = new Map();
  const findings = [];
  const add = (code, source = null, target = null, kinds = []) =>
    findings.push({ code, source, target, kinds });
  for (const manifest of manifests) {
    if (!expectedIds.includes(manifest.chat_id) || byId.has(manifest.chat_id)) {
      add('INVALID_OR_DUPLICATE_ROLE');
      continue;
    }
    const arrays = ['accepts_from', 'sends_to', 'route_edges'];
    if (arrays.some((field) => !Array.isArray(manifest[field])
      || manifest[field].some((entry) => typeof entry !== 'string'))) {
      add('INVALID_ROUTE_FIELDS', manifest.chat_id);
      continue;
    }
    byId.set(manifest.chat_id, manifest);
  }
  for (const id of expectedIds) if (!byId.has(id)) add('MISSING_ROLE', id);
  function requireEdge(code, source, target, kinds) {
    const from = byId.get(source);
    const to = byId.get(target);
    const granted = new Set((from?.route_edges ?? []).flatMap((edge) => {
      const parts = edge.split('|');
      return parts.length === 2 && parts[0] === target ? parts[1].split(',') : [];
    }));
    if (!from?.sends_to.includes(target) || !to?.accepts_from.includes(source)
      || kinds.some((kind) => !granted.has(kind))) add(code, source, target, kinds);
  }
  requireEdge('INTAKE_ROUTE_MISSING', roles.human, roles.master, ['REQUEST']);
  requireEdge('ASSIGNMENT_ROUTE_MISSING', roles.master, roles.deputy, ['TASK_DISPATCH']);
  requireEdge('ROOM_STATUS_MISSING', roles.deputy, roles.room, ['VERIFIED_STATUS']);
  requireEdge('RESULT_RETURN_MISSING', roles.room, roles.deputy, ['AGGREGATE_RESULT']);
  requireEdge('RESULT_RETURN_MISSING', roles.deputy, roles.master, ['AGGREGATE_RESULT']);
  requireEdge('HUMAN_RESULT_MISSING', roles.master, roles.human, ['AGGREGATE_RESULT']);
  for (const team of teams) {
    requireEdge('TEAM_ASSIGNMENT_MISSING', roles.deputy, team, ['TASK_DISPATCH']);
    requireEdge('TEAM_RESULT_MISSING', team, roles.deputy, ['TASK_RESULT']);
    requireEdge('CEO_DIRECT_ASSIGNMENT_MISSING', roles.master, team, ['TASK_DISPATCH']);
    requireEdge('CEO_DIRECT_RESULT_MISSING', team, roles.master, ['TASK_RESULT']);
    requireEdge('TEAM_STATUS_MISSING', team, roles.room, ['VERIFIED_STATUS']);
    for (const peer of teams.filter((id) => id !== team)) {
      // Explicit proposed kinds keep consultation separate from authority to assign.
      requireEdge('PEER_COLLABORATION_MISSING', team, peer, ['COLLAB_REQUEST', 'COLLAB_RESULT']);
    }
  }
  for (const role of expectedIds.filter((id) => id !== roles.human)) {
    requireEdge('DIRECT_ESCALATION_MISSING', role, roles.human, ['DECISION_POINTER']);
  }
  requireEdge('QUALITY_REQUEST_MISSING', roles.deputy, teams[3], ['REVIEW_REQUEST']);
  requireEdge('QUALITY_RESULT_MISSING', teams[3], roles.deputy, ['REVIEW_RESULT']);
  return {
    status: findings.length ? 'REQUIREMENTS_NOT_MET' : 'STATIC_COVERAGE_ONLY',
    requirementRevision: '2026-09-05-ceo-service-chief-direct-teams',
    serviceReady: false,
    messageSent: false,
    notVerified: ['activation', 'endpoint-binding', 'handoff-study-gate',
      'intake-executor', 'task-authorization', 'ack-result-roundtrip', 'retry-dedupe'],
    findings,
  };
}

export function auditProject(root) {
  const directory = join(root, 'docs/team/chats');
  return auditRoutingCoverage(readdirSync(directory).filter((name) => name.endsWith('.md'))
    .map((name) => parseFrontMatter(readFileSync(join(directory, name), 'utf8'), name)));
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv.length > 2) throw new Error('No CLI arguments supported');
    const report = auditProject(resolve(dirname(fileURLToPath(import.meta.url)), '..'));
    console.log(JSON.stringify(report, null, 2));
    process.exitCode = report.findings.length ? 1 : 0;
  } catch {
    // Do not print arbitrary malformed input, provider IDs, or local credentials.
    console.error(JSON.stringify({ status: 'AUDIT_INPUT_INVALID', serviceReady: false }));
    process.exitCode = 2;
  }
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { auditRoutingCoverage, roles, teams } from './team-routing-contract-audit.mjs';

function fixture() {
  const ids = [...Object.values(roles), ...teams];
  const manifests = ids.map((chat_id) => ({ chat_id, accepts_from: [], sends_to: [], route_edges: [] }));
  function edge(source, target, kinds) {
    const from = manifests.find((item) => item.chat_id === source);
    const to = manifests.find((item) => item.chat_id === target);
    if (!from.sends_to.includes(target)) from.sends_to.push(target);
    if (!to.accepts_from.includes(source)) to.accepts_from.push(source);
    from.route_edges.push(`${target}|${kinds.join(',')}`);
  }
  edge(roles.human, roles.master, ['REQUEST']);
  edge(roles.master, roles.deputy, ['TASK_DISPATCH']);
  edge(roles.deputy, roles.room, ['VERIFIED_STATUS']);
  edge(roles.room, roles.deputy, ['AGGREGATE_RESULT']);
  edge(roles.deputy, roles.master, ['AGGREGATE_RESULT']);
  edge(roles.master, roles.human, ['AGGREGATE_RESULT']);
  for (const team of teams) {
    edge(roles.deputy, team, ['TASK_DISPATCH']);
    edge(team, roles.deputy, ['TASK_RESULT']);
    edge(roles.master, team, ['TASK_DISPATCH']);
    edge(team, roles.master, ['TASK_RESULT']);
    edge(team, roles.room, ['VERIFIED_STATUS']);
    for (const peer of teams.filter((id) => id !== team)) edge(team, peer, ['COLLAB_REQUEST', 'COLLAB_RESULT']);
  }
  for (const role of ids.filter((id) => id !== roles.human)) edge(role, roles.human, ['DECISION_POINTER']);
  edge(roles.deputy, teams[3], ['REVIEW_REQUEST']);
  edge(teams[3], roles.deputy, ['REVIEW_RESULT']);
  return manifests;
}

test('static coverage never claims activation or service delivery', () => {
  const result = auditRoutingCoverage(fixture());
  assert.equal(result.status, 'STATIC_COVERAGE_ONLY');
  assert.equal(result.serviceReady, false);
  assert.equal(result.messageSent, false);
  assert.equal(result.findings.length, 0);
});

test('room is not a mandatory assignment hop; deputy dispatch remains required', () => {
  const manifests = fixture();
  assert(!manifests.find((item) => item.chat_id === roles.room).route_edges.some((edge) => edge.includes('TASK_DISPATCH')));
  assert.equal(auditRoutingCoverage(manifests).findings.length, 0);
  const deputy = manifests.find((item) => item.chat_id === roles.deputy);
  deputy.route_edges = deputy.route_edges.filter((edge) => !edge.startsWith(teams[0] + '|'));
  assert(auditRoutingCoverage(manifests).findings.some((item) => item.code === 'TEAM_ASSIGNMENT_MISSING'));
});

test('peer consultation needs both request and response kinds', () => {
  const manifests = fixture();
  manifests.find((item) => item.chat_id === teams[0]).route_edges =
    manifests.find((item) => item.chat_id === teams[0]).route_edges
      .map((edge) => edge.replace('COLLAB_REQUEST,COLLAB_RESULT', 'COLLAB_REQUEST'));
  assert.equal(auditRoutingCoverage(manifests).findings.filter((item) => item.code === 'PEER_COLLABORATION_MISSING').length, 4);
});

test('escalation must be accepted by the human intake, not merely declared by sender', () => {
  const manifests = fixture();
  manifests.find((item) => item.chat_id === roles.human).accepts_from = [roles.master];
  assert.equal(auditRoutingCoverage(manifests).findings.filter((item) => item.code === 'DIRECT_ESCALATION_MISSING').length, 9);
});

test('generic task result does not substitute for independent quality review result', () => {
  const manifests = fixture();
  const quality = manifests.find((item) => item.chat_id === teams[3]);
  quality.route_edges = quality.route_edges.filter((edge) => !edge.includes('REVIEW_RESULT'));
  assert(auditRoutingCoverage(manifests).findings.some((item) => item.code === 'QUALITY_RESULT_MISSING'));
});

test('missing, duplicate and malformed roles fail coverage', () => {
  assert.equal(auditRoutingCoverage([]).status, 'REQUIREMENTS_NOT_MET');
  assert(auditRoutingCoverage([...fixture(), fixture()[0]]).findings.some((item) => item.code === 'INVALID_OR_DUPLICATE_ROLE'));
  const manifests = fixture();
  manifests[0].route_edges = 'not-an-array';
  assert(auditRoutingCoverage(manifests).findings.some((item) => item.code === 'INVALID_ROUTE_FIELDS'));
});
